376. // ── Tests ─────────────────────────────────────────────────────────────────────
377. 
378. #[cfg(test)]
379. mod tests {
380.     use super::*;
381. 
382.     fn solo_yaml() -> serde_yaml::Value {
383.         serde_yaml::from_str(
384.             r#"
385. version: 1
386. site:
387.   name: test
388.   prefix: tst
389. models:
390.   claude-opus:
391.     provider: shell
392.     cli: claude
393.     model: claude-opus
394.   claude-sonnet:
395.     provider: shell
396.     cli: claude
397.     model: claude-sonnet
398.   codex-gpt5:
399.     provider: shell
400.     cli: codex
401.     model: codex-gpt5
402.   copilot:
403.     provider: shell
404.     cli: copilot
405.     model: copilot
406. roles:
407.   proposer: claude-sonnet
408.   drafter: claude-sonnet
409.   reviewer: codex-gpt5
410.   executor: copilot
411.   summariser: claude-sonnet
412. tools:
413.   substrate:
414.     mode: solo
415. pipeline:
416.   - id: specify
417.     role: drafter
418.   - id: plan
419.     role: proposer
420.   - id: assay
421.     runner: derrick
422.   - id: tasks
423.     role: drafter
424.   - id: analyze
425.     role: proposer
426. "#,
427.         )
428.         .unwrap()
429.     }
430. 
431.     #[test]
432.     fn current_mode_reads_solo() {
433.         let yaml = solo_yaml();
434.         assert_eq!(current_mode_str(&yaml), "solo");
435.     }
436. 
437.     #[test]
438.     fn switch_solo_to_crew_updates_mode() {
439.         let mut yaml = solo_yaml();
440.         let old_mode = current_mode_str(&yaml);
441.         let changes = compute_changes(&mut yaml, old_mode, InitMode::Crew).unwrap();
442.         assert_eq!(changes.new_mode, "crew");
443.         assert_eq!(current_mode_str(&yaml), "crew");
444.     }
445. 
446.     #[test]
447.     fn switch_to_crew_adds_bridge_and_foreman() {
448.         let mut yaml = solo_yaml();
449.         let old = current_mode_str(&yaml);
450.         let changes = compute_changes(&mut yaml, old, InitMode::Crew).unwrap();
451.         assert!(changes.steps_added.contains(&"bridge".to_owned()));
452.         assert!(changes.steps_added.contains(&"foreman".to_owned()));
453.         // Verify pipeline in mutated YAML contains the new steps.
454.         let pipeline = yaml["pipeline"].as_sequence().unwrap();
455.         let ids: Vec<_> = pipeline
456.             .iter()
457.             .filter_map(|s| s.get("id")?.as_str())
458.             .collect();
459.         assert!(ids.contains(&"bridge"));
460.         assert!(ids.contains(&"foreman"));
461.     }
462. 
463.     #[test]
464.     fn switch_crew_to_solo_removes_bridge_and_foreman() {
465.         let mut yaml = solo_yaml();
466.         // First go to crew.
467.         let old = current_mode_str(&yaml);
468.         compute_changes(&mut yaml, old, InitMode::Crew).unwrap();
469.         // Then switch back to solo.
470.         let old2 = current_mode_str(&yaml);
471.         let changes = compute_changes(&mut yaml, old2, InitMode::Solo).unwrap();
472.         assert!(!changes.steps_removed.is_empty());
473.         let pipeline = yaml["pipeline"].as_sequence().unwrap();
474.         let ids: Vec<_> = pipeline
475.             .iter()
476.             .filter_map(|s| s.get("id")?.as_str())
477.             .collect();
478.         assert!(!ids.contains(&"bridge"));
479.         assert!(!ids.contains(&"foreman"));
480.     }
481. 
482.     #[test]
483.     fn switch_to_crew_updates_proposer_role() {
484.         let mut yaml = solo_yaml();
485.         // In solo mode the proposer is claude-sonnet; crew recommends claude-opus.
486.         let old = current_mode_str(&yaml);
487.         let changes = compute_changes(&mut yaml, old, InitMode::Crew).unwrap();
488.         let proposer_change = changes
489.             .role_changes
490.             .iter()
491.             .find(|(r, _, _)| r == "proposer");
492.         assert!(
493.             proposer_change.is_some(),
494.             "expected proposer role to change; changes: {changes:?}",
495.         );
496.         let (_, _, new_model) = proposer_change.unwrap();
497.         assert_eq!(new_model, "claude-opus");
498.     }
499. 
500.     #[test]
501.     fn detect_inflight_no_runs_dir() {
502.         let tmp = tempfile::tempdir().unwrap();
503.         // No .derrick/runs directory at all → empty.
504.         assert!(detect_inflight_runs(tmp.path()).is_empty());
505.     }
506. 
507.     #[test]
508.     fn detect_inflight_finished_run_not_reported() {
509.         let tmp = tempfile::tempdir().unwrap();
510.         let runs = tmp.path().join(".derrick").join("runs").join("run-1");
511.         std::fs::create_dir_all(&runs).unwrap();
512.         std::fs::write(
513.             runs.join("manifest.json"),
514.             r#"{"started_at":"2026-01-01T00:00:00Z","finished_at":"2026-01-01T01:00:00Z","status":"success","steps":[],"tokens_in":0,"tokens_out":0}"#,
515.         )
516.         .unwrap();
517.         assert!(detect_inflight_runs(tmp.path()).is_empty());
518.     }
519. 
520.     #[test]
521.     fn detect_inflight_unfinished_run_is_reported() {
522.         let tmp = tempfile::tempdir().unwrap();
523.         let runs = tmp.path().join(".derrick").join("runs").join("run-42");
524.         std::fs::create_dir_all(&runs).unwrap();
525.         std::fs::write(
526.             runs.join("manifest.json"),
527.             r#"{"started_at":"2026-01-01T00:00:00Z","finished_at":null,"status":"success","steps":[],"tokens_in":0,"tokens_out":0}"#,
528.         )
529.         .unwrap();
530.         let inflight = detect_inflight_runs(tmp.path());
531.         assert_eq!(inflight, vec!["run-42"]);
532.     }
533. }
